import { StyleFn } from "..";

export const Skeleton: StyleFn = (theme, mode) => {
  const { color, size } = theme;

  const scanGradient = {
    content: '""',
    background: `linear-gradient(90deg, #ffffff00, #ffffff8a ${size.spacing[40]}, #ffffff00 ${size.spacing[80]}) no-repeat`,
    "background-size": `${size.spacing[80]} 100%`,
    animation: "$gradient 3s linear infinite",
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
  };
  return {
    "@keyframes gradient": {
      "0%": {
        "background-position-x": `-${size.spacing[80]}`,
      },
      "30%": {
        "background-position-x": `calc(100% + ${size.spacing[80]})`,
      },
      "100%": {
        "background-position-x": `calc(100% + ${size.spacing[80]})`,
      },
    },
    root: {
      position: "relative",
      "&:before": {
        content: '""',
        "background-color": color.surface.componentonbackground.minimal[mode],
        "border-radius": "3px",
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
      },
      "&:after": scanGradient,
      "&$_secondary:before": {
        "background-color": color.surface.componentonbackground.moderate[mode],
      },
      "&$_text": {
        "&::before": {
          "background-color": color.surface.componentonbackground.strong[mode],
        },
        "&$_secondary:before": {
          "background-color":
            color.surface.componentonbackground.moderate[mode],
        },
      },
    },
    _secondary: {},
    _text: {},
    _component: {
      "&:after": scanGradient,
      "& $root:after": {
        background: "none",
      },
    },
  };
};
